554	    private <T> T findEntityById(Supplier<T> supplier) {
555	        try {
556	            return supplier.get();
557	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
558	            // Just ignore not found exceptions for Jdbc/Jpa realization
559	            return null;
560	        }
561	    }
